/* @lc app=leetcode id=3776 lang=kotlin */ class Solution { fun minMoves(balance: IntArray): Long = balance.indices.firstOrNull { balance[it] < 0 }.let { p -> if (p == null) 0L else (-balance[p].toLong()).let { need -> balance.indices.filter { balance[it] > 0 }.sortedBy { Math.min(Math.abs(it - p), balance.size - Math.abs(it - p)) }.fold(Triple(need, 0L, 0L)) { (rem, cost, _), i -> minOf(rem, balance[i].toLong()).let { t -> Triple(rem - t, cost + t * minOf(Math.abs(i - p), balance.size - Math.abs(i - p)), 0L) } }.let { (rem, cost, _) -> if (rem > 0) -1L else cost } } } }